use super::*;
use semio_framework_value::ErasedSnapshotRetirement;
use semio_framework_value_native_owned::{native_decoding::NativeDecodeAllocation, native_decoding::NativeDecodeAllocationPort, native_decoding::NativeDecodeRetirementRecipient};
#[derive(Clone,Copy)]struct OriginalPages<'a>{pages:&'a[&'a[u8]],page_bytes:usize,identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for OriginalPages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{if index>=self.identity.extent{return None}self.pages.get(index/self.page_bytes)?.get(index%self.page_bytes).copied()}}
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(operation)}
fn hex(value:&str)->Vec<u8>{value.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn receipt(owner:&mut RetainedHistorySourceFrames,g:RetainedCloneGrant){let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((p.retained_capacity_bytes,p.released_bytes),(0,0));}
async fn original_bytes(law:&serde_json::Value)->Vec<u8>{let options=protocol::format::WriteOptions{required_flags:protocol::REQUIRED_HASH_CHAIN,optional_flags:protocol::OPTIONAL_CANONICAL};let mut writer=protocol::format::SprWriter::begin(Vec::new(),&options).await.unwrap();for row in law["records"].as_array().unwrap(){writer.write_record(row["kind"].as_u64().unwrap()as u8,row["flags"].as_u64().unwrap()&2!=0,&hex(row["payloadHex"].as_str().unwrap()),protocol::codec::ids::CodecId(0)).await.unwrap();}writer.commit().await.unwrap();writer.into_sink().await}
#[test]fn original_history_source_frames_native_verify_pages_before_any_range_publication(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let limits:HistoryReadLimits=serde_json::from_value(law["limits"].clone()).unwrap();let control_limit=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let axes=&law["grant"];let n=|key:&str|axes[key].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};let committed=semio_framework_async::poll::resolve_ready(original_bytes(&law));assert_eq!(&committed[..32],hex(law["headerHex"].as_str().unwrap()));let mut independent=blake3::Hasher::new();independent.update(blake3::hash(&committed[..32]).as_bytes());let mut position=32;while committed[position]!=66{let start=position;let mut body=0;let mut shift=0;loop{let byte=committed[position];position+=1;body|=usize::from(byte&127)<<shift;if byte&128==0{break}shift+=7}let end=position+body+8;independent.update(blake3::hash(&committed[start..end]).as_bytes());position=end;}assert_eq!(&committed[position+35..position+67],independent.finalize().as_bytes());
 let mut original=vec![0xaa];original.extend_from_slice(&committed);let end=original.len();original.push(0xbb);for paged in[false,true]{let page_bytes=if paged{law["source"]["pageBytes"].as_u64().unwrap()as usize}else{original.len()};let pages=original.chunks(page_bytes).collect::<Vec<_>>();let identity=OriginalWireSourceIdentity{address:original.as_ptr()as usize,extent:original.len(),authority:if paged{Some((43,7))}else{None}};let source=OriginalPages{pages:&pages,page_bytes,identity};for cancellation in[0,1,7,17,100000]{let mut allocation=|_:NativeDecodeAllocation|->Result<(),ValueError>{panic!("original frame metadata requested allocation")};let port:&mut NativeDecodeAllocationPort<'_>=&mut allocation;let mut callback=|_|true;let mut retirement=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(control_limit,&mut callback,port);control.install_retirement_recipient(&mut retirement).unwrap();
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(owner,born,released)=observe(||RetainedHistorySourceFrames::admit(&source,(1,end),limits,&control,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0));}
  let(owner,born,released)=observe(||RetainedHistorySourceFrames::admit(&source,(1,end),limits,&control,g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();receipt(&mut owner,g);assert_eq!(owner.original_range(),(1,end));for changed_identity in[OriginalWireSourceIdentity{address:identity.address+1,..identity},OriginalWireSourceIdentity{extent:identity.extent-1,..identity},OriginalWireSourceIdentity{authority:Some((43,8)),..identity}]{let changed=OriginalPages{identity:changed_identity,..source};let(result,born,released)=observe(||owner.step(&changed,&mut control,g));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let mut foreign_callback=|_|true;let mut foreign=NativeDecodeControl::new(control_limit,&mut foreign_callback);let(result,born,released)=observe(||owner.step(&source,&mut foreign,g));assert!(result.is_err());assert_eq!((born,released),(0,0));drop(foreign);
  let mut received=0;for _ in 0..cancellation{if owner.is_ready(){break}if owner.frame_is_receivable(){let mut frame=None;let(moved,born,released)=observe(||owner.take_frame_into(&source,&control,&mut frame,g).unwrap());assert!(moved);assert_eq!((born,released),(0,0));receipt(&mut owner,g);let frame=frame.take().unwrap();assert!(owner.verified);assert!(frame.original_range().0>=33);assert!(frame.original_range().1<=end);let range=frame.payload_range();if received<law["records"].as_array().unwrap().len(){let expected=&law["records"][received];assert_eq!(frame.kind(),expected["kind"].as_u64().unwrap()as u8);assert_eq!(frame.flags(),expected["flags"].as_u64().unwrap()as u8);assert_eq!(&original[range.0..range.1],hex(expected["payloadHex"].as_str().unwrap()));}else{assert_eq!(frame.kind(),protocol::REC_COMMIT);assert_eq!(range.1-range.0,64)}received+=1;continue}let d=owner.demands(&source,&control,g.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g},RetainedCloneGrant{maximum_copy_bytes:0,..g}]{if denied.maximum_copy_bytes==0&&d.copy_bytes==0{continue}let before=owner.consumed_end();let(step,born,released)=observe(||owner.step(&source,&mut control,denied).unwrap());assert_eq!(step,RetainedHistorySourceFramesStep::Blocked);assert_eq!((born,released),(0,0));assert_eq!(owner.consumed_end(),before);assert!(owner.receipt().is_none());}let(step,born,released)=observe(||owner.step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistorySourceFramesStep::Blocked);assert_eq!((born,released),(0,0));receipt(&mut owner,g);if !owner.verified{assert_eq!(received,0)}}if cancellation==100000{assert!(owner.is_ready());assert_eq!(received,law["records"].as_array().unwrap().len()+1);assert_eq!(owner.committed_sequence(),1)}owner.cancel();let(step,born,released)=observe(||owner.close_step(&source,&control,g).unwrap());assert_eq!(step,RetainedHistorySourceFramesStep::Closed);assert_eq!((born,released),(0,0));receipt(&mut owner,g);assert!(owner.terminal_is_empty());let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));assert_eq!(control.owned_bytes(),0);drop(control);assert!(retirement.terminal_is_empty());}}
 for bytes in[&committed[..committed.len()-1],&committed[..32]]{let pages=[bytes];let source=OriginalPages{pages:&pages,page_bytes:bytes.len(),identity:OriginalWireSourceIdentity{address:bytes.as_ptr()as usize,extent:bytes.len(),authority:Some((43,7))}};let mut callback=|_|true;let mut control=NativeDecodeControl::new(control_limit,&mut callback);let mut owner=RetainedHistorySourceFrames::admit(&source,(0,bytes.len()),limits,&control,g).unwrap().unwrap();receipt(&mut owner,g);let mut rejected=false;for _ in 0..100000{match owner.step(&source,&mut control,g){Ok(_)=>{receipt(&mut owner,g);assert!(!owner.frame_is_receivable())},Err(_)=>{receipt(&mut owner,g);rejected=true;break}}}assert!(rejected);owner.cancel();owner.close_step(&source,&control,g).unwrap();receipt(&mut owner,g);assert!(owner.terminal_is_empty());}
}
